public class AnimacionPostProduccion extends Animacion {

    private double recursosLicenciados;

    public AnimacionPostProduccion(String codigo, String estudio,
                                   String proyecto, double horasEstimadas,
                                   Horario horario, int fotogramas,
                                   double recursosLicenciados) {

        // Inicializa los datos comunes y los fotogramas en Animacion.
        super(codigo, estudio, proyecto, horasEstimadas, horario, fotogramas);

        // Aplica la regla del enunciado de rechazar valores no positivos.
        if (!Double.isFinite(recursosLicenciados)
                || recursosLicenciados <= 0) {
            throw new IllegalArgumentException(
                "El valor de los recursos licenciados debe ser positivo y finito."
            );
        }

        this.recursosLicenciados = recursosLicenciados;
    }

    // Calcula el costo de animación con los cargos de postproducción.
    @Override
    public double calcularCosto() {
        // Reutiliza el costo de Animacion y agrega Q80 y el 5 % de recursos.
        return super.calcularCosto() + 80.0 + 0.05 * recursosLicenciados;
    }

    // Calcula el tiempo de entrega incluyendo la postproducción.
    @Override
    public int calcularTiempoEntrega() {
        // Agrega 12 horas al plazo calculado por Animacion.
        return super.calcularTiempoEntrega() + 12;
    }

    // Establece dos intentos totales para esta categoría.
    @Override
    public int getIntentosMaximos() {
        return 2;
    }

    // Identifica esta categoría por separado en consultas y reportes.
    @Override
    public String getCategoria() {
        return "Animación con postproducción";
    }

    public double getRecursosLicenciados() {
        return recursosLicenciados;
    }
}